from pedantic import retry, validate, require_kwargs, count_calls, rename_kwargs, trace_class, timer_class

@trace_class
@timer_class
class RomanNumeralConverter:
    """A class to convert Roman numerals to integers."""

    def __init__(self):
        """Initialize the Roman numeral converter with default values."""
        self.roman_to_int_map = {
            'I': 1,
            'V': 5,
            'X': 10,
            'L': 50,
            'C': 100,
            'D': 500,
            'M': 1000
        }
        self.roman_string = ""
        self.roman_string_s = ""  # Ends with '_s' as per guidelines

    @count_calls
    @rename_kwargs
    @validate
    @require_kwargs
    @retry
    def a_chx_convert_to_integer_b(self, roman_string: str) -> int:
        """
        Convert a Roman numeral string to an integer.

        Parameters:
        roman_string (str): A string representing a Roman numeral.

        Returns:
        int: The integer equivalent of the Roman numeral.

        Raises:
        ValueError: If the input is not a valid Roman numeral.
        """
        try:
            # Validate that the input is a string
            if not isinstance(roman_string, str):
                raise ValueError("Input must be a string.")

            # Check for empty string
            if not roman_string:
                raise ValueError("Input string cannot be empty.")

            # Initialize variables
            total = 0
            prev_value = 0

            # Iterate over the Roman numeral string
            for char in reversed(roman_string):
                current_value = self.roman_to_int_map.get(char, 0)

                # If the current value is less than the previous value, subtract it
                if current_value < prev_value:
                    total -= current_value
                else:
                    total += current_value

                prev_value = current_value

            # Check if the result is a valid integer
            if not isinstance(total, int) or total < 1:
                raise ValueError("Invalid Roman numeral.")

            return total

        except Exception as e:
            # Log the error and re-raise it
            print(f"An error occurred: {e}")
            raise
